<Project Sdk="Microsoft.NET.Sdk"><PropertyGroup><OutputType>Exe</OutputType><TargetFramework>net11.0</TargetFramework><ImplicitUsings>enable</ImplicitUsings><Nullable>enable</Nullable></PropertyGroup>
<ItemGroup><PackageReference Include="Microsoft.CodeAnalysis.CSharp" Version="4.*" /></ItemGroup></Project>
E
cat > P.cs <<'E'
using Microsoft.CodeAnalysis; using Microsoft.CodeAnalysis.CSharp; using Microsoft.CodeAnalysis.CSharp.Syntax;
foreach (var f in Directory.EnumerateFiles(args[0],"*.cs",SearchOption.AllDirectories)) {
 if (f.Contains("\\obj\\")||f.Contains("\\bin\\")) continue;
 var root = CSharpSyntaxTree.ParseText(File.ReadAllText(f)).GetRoot();
 foreach (var m in root.DescendantNodes().OfType<BaseMethodDeclarationSyntax>().Cast<SyntaxNode>().Concat(root.DescendantNodes().OfType<LocalFunctionStatementSyntax>())) {
  var body = (m as BaseMethodDeclarationSyntax)?.Body ?? (SyntaxNode?)(m as BaseMethodDeclarationSyntax)?.ExpressionBody ?? (m as LocalFunctionStatementSyntax)?.Body;
  if (body==null) continue;
  int cc=1;
  foreach (var n in body.DescendantNodesAndSelf()) {
   if (n is IfStatementSyntax||n is ForStatementSyntax||n is ForEachStatementSyntax||n is WhileStatementSyntax||n is DoStatementSyntax||n is CatchClauseSyntax||n is ConditionalExpressionSyntax||n is SwitchSectionSyntax||n is SwitchExpressionArmSyntax||n is ConditionalAccessExpressionSyntax) cc++;
   else if (n is BinaryExpressionSyntax b && (b.IsKind(SyntaxKind.LogicalAndExpression)||b.IsKind(SyntaxKind.LogicalOrExpression)||b.IsKind(SyntaxKind.CoalesceExpression))) cc++;
   else if (n is BinaryPatternSyntax bp && (bp.IsKind(SyntaxKind.OrPattern)||bp.IsKind(SyntaxKind.AndPattern))) cc++;
  }
  var ls = m.GetLocation().GetLineSpan(); int lines = ls.EndLinePosition.Line-ls.StartLinePosition.Line+1;
  var name = (m as MethodDeclarationSyntax)?.Identifier.Text ?? (m as LocalFunctionStatementSyntax)?.Identifier.Text ?? m.Kind().ToString();
  if (cc>5||lines>20) Console.WriteLine($"{(cc>5?"CC="+cc:"")} {(lines>20?"L="+lines:"")} {Path.GetRelativePath(args[0],f)}:{ls.StartLinePosition.Line+1} {name}");
 }}
E
